sys_script_client.script:
function onSubmit() {
    var sig = JSON.stringify([
        g_form.getValue('api_version') || 'v1',
        g_form.getValue('organisation_code') || '',
        g_form.getValue('client_id') || '',
        g_form.getValue('api_key') || '',
        g_form.getValue('user_api_key') || '',
        g_form.getValue('client_secret') || ''
    ]);
    if (sig !== (g_scratchpad.doppelTestedSig || '')) {
        g_form.setValue('connectivity_verified', 'false');
        g_form.addErrorMessage('Connection settings changed. Click Test Connectivity and get a successful result before saving.');
        return false;
    }
    return true;
}
